// swift-tools-version:5.9
import PackageDescription

// Development build and tests. The shipping app is built from Diskwise.xcodeproj
// (generated by XcodeGen from project.yml), which uses the same sources.
//
// The executable target below is named "DiskwiseDev" (not "Diskwise") so its
// implicit SwiftPM product does not collide with the Xcode app target/scheme
// named "Diskwise" when this package is used as a local dependency of
// Diskwise.xcodeproj. It still builds from Sources/Diskwise unchanged.
let package = Package(
    name: "Diskwise",
    platforms: [.macOS(.v14)],
    products: [.library(name: "DiskwiseCore", targets: ["DiskwiseCore"])],
    targets: [
        .target(name: "DiskwiseCore"),
        .executableTarget(name: "DiskwiseDev", dependencies: ["DiskwiseCore"], path: "Sources/Diskwise"),
        .testTarget(name: "DiskwiseCoreTests", dependencies: ["DiskwiseCore"]),
    ]
)
